package com.backendSupermercado.supermercasdo.modules.reportes.personal.model;
public enum TipoReportePersonal { EMPLEADOS("empleados-general","Reporte general de empleados"), CONTRATOS("contratos-general","Reporte general de contratos"), ASISTENCIA("asistencia-general","Reporte general de asistencia"), ATRASOS("atrasos-inasistencias","Reporte de atrasos e inasistencias"), HORAS("horas-trabajadas","Reporte de horas trabajadas"), JUSTIFICADAS("asistencias-justificadas","Reporte de asistencias justificadas"), PERMISOS("permisos-laborales","Reporte de permisos laborales"); private final String ruta,titulo; TipoReportePersonal(String r,String t){ruta=r;titulo=t;} public String ruta(){return ruta;} public String titulo(){return titulo;} public static TipoReportePersonal desdeRuta(String r){for(var t:values())if(t.ruta.equalsIgnoreCase(r))return t;throw new IllegalArgumentException("Reporte de personal no válido");}}
